/* Hand-authored learning curriculum: lessons are educational guidance, not real execution. */
'use strict';
const LT = (ar, fr, en) => ({ ar, fr, en });
const LESSON_MODULES = [
    { id: 'b-start', shell: 'bash', name: LT('الانطلاقة مع Bash', 'Premiers pas avec Bash', 'Starting with Bash'), intro: LT('ما معنى الـ Shell وكيف تقرأ المخرجات وتطلب المساعدة؟', 'Comprendre le shell, ses sorties et son aide intégrée.', 'Understand the shell, outputs and built-in help.') },
    { id: 'b-files', shell: 'bash', name: LT('الملفات والمسارات', 'Fichiers et chemins', 'Files and paths'), intro: LT('إنشاء الملفات ونقلها والعثور عليها دون المخاطرة ببياناتك.', 'Créer, déplacer et trouver des fichiers sans risque inutile.', 'Create, move and find files without avoidable risk.') },
    { id: 'b-text', shell: 'bash', name: LT('قراءة النصوص والسجلات', 'Lire textes et journaux', 'Reading text and logs'), intro: LT('القراءة والبحث والفرز وتحويل النصوص.', 'Lire, rechercher, trier et transformer des textes.', 'Read, search, sort and transform text.') },
    { id: 'b-pipes', shell: 'bash', name: LT('Pipelines والإخراج', 'Pipelines et redirections', 'Pipelines and redirection'), intro: LT('ربط الأوامر وفصل stdout عن stderr والتحكم في التنفيذ.', 'Relier les commandes et gérer les flux de sortie.', 'Chain commands and manage output streams.') },
    { id: 'b-data', shell: 'bash', name: LT('CSV وJSON والتحليل', 'CSV, JSON et analyse', 'CSV, JSON and analysis'), intro: LT('تصفية بيانات منظمة وتشخيص الاختلافات بين الملفات.', 'Filtrer les données structurées et comparer les fichiers.', 'Filter structured data and compare files.') },
    { id: 'b-system', shell: 'bash', name: LT('إدارة Linux', 'Administration Linux', 'Linux administration'), intro: LT('المستخدمون والعمليات والتخزين والصلاحيات.', 'Utilisateurs, processus, stockage et permissions.', 'Users, processes, storage and permissions.') },
    { id: 'b-network', shell: 'bash', name: LT('الشبكات والتشخيص', 'Réseaux et diagnostic', 'Networking and diagnostics'), intro: LT('فهم العناوين والمنافذ وDNS والتحقق من الخدمات.', 'Comprendre IP, ports, DNS et services.', 'Understand IP addresses, ports, DNS and services.') },
    { id: 'b-automation', shell: 'bash', name: LT('من الأوامر إلى الأتمتة', 'Des commandes à l’automatisation', 'From commands to automation'), intro: LT('المتغيرات والشروط والتكرار وكتابة سكربت آمن.', 'Variables, conditions, boucles et scripts sûrs.', 'Variables, conditions, loops and safer scripts.') },
    { id: 'p-start', shell: 'powershell', name: LT('مبادئ PowerShell', 'Découvrir PowerShell', 'PowerShell foundations'), intro: LT('تعرف على Cmdlets والمساعدة ونموذج الكائنات.', 'Découvrir les cmdlets, l’aide et les objets.', 'Learn cmdlets, help and the object model.') },
    { id: 'p-files', shell: 'powershell', name: LT('الملفات والمجلدات', 'Fichiers et dossiers', 'Files and directories'), intro: LT('التصفح والإنشاء والنسخ وإدارة المسارات.', 'Navigation, création, copie et chemins.', 'Navigation, creation, copying and paths.') },
    { id: 'p-content', shell: 'powershell', name: LT('محتوى الملفات', 'Contenu des fichiers', 'Working with file content'), intro: LT('قراءة الملفات وتصفية النصوص وحفظ النتائج.', 'Lire, filtrer et enregistrer les contenus.', 'Read, filter and save file contents.') },
    { id: 'p-objects', shell: 'powershell', name: LT('الكائنات والـ Pipeline', 'Objets et pipeline', 'Objects and pipelines'), intro: LT('بدل تمرير النصوص فقط، مرّر كائنات بخصائصها.', 'Transmettre des objets et leurs propriétés.', 'Pass objects with properties rather than just text.') },
    { id: 'p-data', shell: 'powershell', name: LT('CSV وJSON والتقارير', 'CSV, JSON et rapports', 'CSV, JSON and reports'), intro: LT('تحويل البيانات إلى كائنات وجداول وتقارير.', 'Transformer les données en objets et rapports.', 'Transform data into objects and reports.') },
    { id: 'p-system', shell: 'powershell', name: LT('إدارة النظام', 'Administration système', 'System administration'), intro: LT('العمليات والخدمات والمتغيرات وأخطاء التنفيذ.', 'Processus, services, variables et erreurs.', 'Processes, services, variables and errors.') },
    { id: 'p-network', shell: 'powershell', name: LT('أوامر الشبكات', 'Commandes réseau', 'Networking cmdlets'), intro: LT('تعرّف على IP وTCP والاتصال ومبادئ التشخيص.', 'Examiner IP, TCP et la connectivité.', 'Inspect IP, TCP and connectivity.') },
    { id: 'p-automation', shell: 'powershell', name: LT('أتمتة PowerShell', 'Automatisation PowerShell', 'PowerShell automation'), intro: LT('تكوين منطق السكربتات والتحقق من النتائج.', 'Créer la logique et vérifier les résultats.', 'Build script logic and validate results.') }
];
const LESSONS = [];
function add(module, title, goal, concept, syntax, example, explain, pitfall, lab, refs) {
    const mod = LESSON_MODULES.find(m => m.id === module); if (!mod) throw Error('Unknown module ' + module);
    LESSONS.push({ id: module + '-' + String(LESSONS.filter(x => x.module === module).length + 1), module, shell: mod.shell, title, goal, concept, syntax, example, explain, pitfall, lab: lab || '', refs: refs || [], minutes: 8 + 2 * (LESSONS.filter(x => x.module === module).length % 3) });
}
// BASH · 01 · Foundations
add('b-start', LT('ما هو Terminal وShell؟', 'Terminal et shell : différences', 'Terminal vs shell'), LT('تميّز بين نافذة Terminal والمفسّر Bash.', 'Distinguer la fenêtre terminal de l’interpréteur Bash.', 'Distinguish the terminal window from Bash itself.'), LT('الـTerminal واجهة إدخال وعرض؛ Bash برنامج يقرأ الأوامر ويفسّرها. الأمر يعمل بصلاحيات المستخدم الحالي، وليس بالضرورة root.', 'Le terminal affiche les entrées/sorties; Bash interprète les commandes. Les droits sont ceux de l’utilisateur courant.', 'A terminal displays input/output; Bash interprets commands. Commands run with the current user’s permissions.'), 'whoami\npwd\necho "Hello shell"', 'whoami\npwd\necho "Hello shell"', LT('يعرض whoami الحساب الحالي، وpwd المسار النشط، وecho نصاً. كل سطر أمر مستقل.', 'whoami affiche l’utilisateur, pwd le répertoire courant et echo du texte; chaque ligne est distincte.', 'whoami prints the account, pwd prints the current folder and echo prints text; each line is separate.'), LT('لا تفترض أن أوامر المختبر تعمل على جهازك الحقيقي؛ بياناته افتراضية.', 'Les données du laboratoire sont virtuelles, pas celles de votre machine.', 'Lab data is virtual; it is not data from your device.'), 'whoami', ['whoami', 'pwd', 'echo']);
add('b-start', LT('أين أنا؟ التنقل بالمسارات', 'Se repérer dans les chemins', 'Navigating paths'), LT('تنتقل بين المجلدات بالمسارات المطلقة والنسبية.', 'Parcourir les dossiers avec des chemins absolus et relatifs.', 'Move between folders using absolute and relative paths.'), LT('المسار / يبدأ من الجذر، أما المسار النسبي فيبدأ من المجلد الحالي. الرمز .. يعني الأب و~ يعني المنزل.', 'Un chemin commençant par / est absolu; un chemin relatif part du dossier courant. .. est le parent et ~ le domicile.', 'A path starting with / is absolute; a relative path starts at the current directory. .. means parent and ~ means home.'), 'pwd | cd PATH | ls -la', 'pwd\nls\ncd Documents\npwd\ncd ..', LT('ابدأ بـpwd لمعرفة الموقع، ثم استعمل cd للدخول أو الرجوع وls لاستعراض المحتوى.', 'Utilisez pwd pour voir le chemin, cd pour changer de dossier et ls pour lister les éléments.', 'Use pwd for the current path, cd to change folders, and ls to list items.'), LT('الفراغات داخل اسم المسار تحتاج إلى اقتباس، مثل cd "My Folder".', 'Les chemins contenant des espaces doivent être entre guillemets.', 'Quote paths that contain spaces, such as cd "My Folder".'), 'pwd', ['pwd', 'cd', 'ls']);
add('b-start', LT('قراءة المساعدة قبل التنفيذ', 'Chercher de l’aide', 'Read help before running'), LT('تتعرف على طريقة استعمال أي أمر دون التخمين.', 'Trouver l’usage des commandes sans deviner.', 'Find command usage without guessing.'), LT('بعض الأدوات تدعم --help، والعديد منها موثق عبر man. النوع built-in مثل cd قد يحتاج help cd في Bash الحقيقي.', 'Certaines commandes prennent --help et sont documentées par man. Pour les commandes internes, help peut convenir.', 'Many tools support --help or man pages. Built-ins such as cd may use Bash help.'), 'command --help | man command | help builtin', 'help\nwhich ls\necho ok', LT('يبيّن help داخل المختبر الأوامر التي يحاكيها فقط، بينما man في Linux الحقيقي يوفر صفحات أوسع.', 'Dans le laboratoire help liste seulement les commandes simulées; sur Linux, man donne une documentation plus complète.', 'Lab help lists only simulated commands; on real Linux man provides broader documentation.'), LT('لا تعتمد على مثال من إصدار آخر إذا كانت الخيارات مختلفة؛ تحقق من المساعدة المحلية.', 'Vérifiez l’aide locale: les options peuvent changer selon la version.', 'Check local help because options can differ between versions.'), 'help', ['which', 'type', 'man']);
add('b-start', LT('الاقتباس والمتغيرات الخاصة', 'Guillemets et substitutions', 'Quoting and expansion'), LT('تفرق بين النص الحرفي وتوسيع المتغيرات.', 'Différencier le texte littéral et l’expansion des variables.', 'Tell literal text from variable expansion.'), LT('الاقتباس المفرد يحافظ على $NAME كما هو. المزدوج يسمح بتوسيع متغيرات Bash ويمنع تقسيم الكلمات بسبب الفراغات.', 'Les apostrophes gardent $NAME littéral; les guillemets doubles permettent son expansion et préservent les espaces.', 'Single quotes keep $NAME literal; double quotes expand it while protecting spaces.'), 'echo "$NAME" | echo \'$NAME\'', 'export NAME=student\necho "$NAME"\necho \'$NAME\'', LT('قارن السطرين: الأول يعرض قيمة NAME والثاني يعرض النص $NAME.', 'Comparez : le premier affiche la valeur de NAME et le second le texte $NAME.', 'Compare: the first prints NAME’s value, the second prints the text $NAME.'), LT('كتابة echo $NAME دون اقتباس قد تقسّم القيمة إلى كلمات في Bash الحقيقي.', 'echo $NAME sans guillemets peut découper une valeur en plusieurs mots.', 'Unquoted $NAME may be split into words by real Bash.'), 'export NAME=student; echo "$NAME"', ['echo', 'export', 'printenv']);
// BASH · 02 · Files
add('b-files', LT('إنشاء الملفات والمجلدات', 'Créer fichiers et dossiers', 'Create files and directories'), LT('تنشئ مساحة تدريب مرتبة.', 'Construire un espace de travail organisé.', 'Build an organized workspace.'), LT('mkdir ينشئ مجلداً، وtouch ينشئ ملفاً فارغاً أو يحدّث توقيته. الخيار -p ينشئ المجلدات الأب الناقصة.', 'mkdir crée un dossier et touch un fichier vide ou actualise son horodatage. -p crée les parents absents.', 'mkdir creates directories; touch creates an empty file or updates timestamps. -p makes missing parents.'), 'mkdir -p DIR/SUBDIR | touch FILE', 'mkdir -p training/week1\ntouch training/week1/notes.txt\nls training/week1', LT('ينشأ أولاً المسار المتداخل ثم الملف. تحقق بعد التنفيذ بواسطة ls.', 'Créez le chemin imbriqué avant le fichier et vérifiez avec ls.', 'Create the nested path before the file and check it using ls.'), LT('بدون -p قد يفشل mkdir إذا كان المجلد الأب غير موجود.', 'Sans -p, mkdir peut échouer si le parent manque.', 'Without -p, mkdir may fail if a parent directory is missing.'), 'mkdir -p training/week1; touch training/week1/notes.txt', ['mkdir', 'touch', 'ls']);
add('b-files', LT('النسخ والنقل وإعادة التسمية', 'Copier, déplacer, renommer', 'Copy, move and rename'), LT('تفرق بين النسخ والنقل وكيفية التعامل مع الوجهة.', 'Différencier copie et déplacement.', 'Understand copying versus moving.'), LT('cp يترك الأصل ويُنشئ نسخة. mv ينقل الملف أو يعيد تسميته. الدليل الموجود كوجهة يعني غالباً وضع الملف داخله.', 'cp conserve la source; mv la déplace ou la renomme. Une destination qui est un dossier reçoit le fichier.', 'cp keeps the original; mv moves or renames it. An existing destination directory receives the source.'), 'cp SOURCE DEST | mv SOURCE DEST', 'cp notes.txt notes-copy.txt\nmv notes-copy.txt notes-final.txt\nls', LT('انظر أسماء الملفات بعد النسخ، وبعد نقل النسخة إلى اسم جديد.', 'Vérifiez les noms après la copie et le renommage de la copie.', 'Observe file names after copying and renaming the copy.'), LT('قبل نسخ ملف إلى اسم موجود، تحقق من احتمال استبدال محتواه.', 'Une copie vers un fichier existant peut remplacer son contenu.', 'Copying to an existing filename may overwrite its contents.'), 'cp notes.txt notes-copy.txt', ['cp', 'mv']);
add('b-files', LT('الحذف بأمان', 'Supprimer avec prudence', 'Delete with care'), LT('تتعلم لماذا rm يحتاج إلى مراجعة قبل التنفيذ.', 'Comprendre pourquoi rm demande une vérification.', 'Learn why rm needs careful review.'), LT('rm يحذف الملفات؛ rm -r يحذف المجلد ومحتوياته. في Linux الحقيقي لا يوجد سلة محذوفات تلقائية لهذه الأوامر.', 'rm supprime les fichiers et rm -r les dossiers récursivement, sans corbeille automatique.', 'rm removes files; rm -r removes directories recursively, usually bypassing the trash.'), 'rm FILE | rm -r DIR', 'touch training/tmp.txt\nls training\nrm training/tmp.txt', LT('راجع المسار بـls قبل الحذف وتجنب استعمال -rf على مسارات لم تتحقق منها.', 'Vérifiez le chemin avec ls avant de supprimer, surtout avec -r ou -f.', 'Inspect the path with ls before deletion, especially when considering -r or -f.'), LT('rm -rf لا يطلب تأكيداً وقد يدمر بيانات حقيقية؛ لا تستعمله للتجربة على جهازك.', 'rm -rf peut effacer des données sans confirmation; évitez de l’essayer sur vos vrais fichiers.', 'rm -rf may delete real data without prompting; do not experiment on real files.'), 'touch training/remove-me.txt; rm training/remove-me.txt', ['rm', 'rmdir', 'ls']);
add('b-files', LT('البحث عن الملفات', 'Rechercher des fichiers', 'Find files by name'), LT('تبحث حسب الاسم والموقع بدل تصفح كل مجلد.', 'Rechercher par nom et emplacement.', 'Search by name and location.'), LT('find يمشي داخل شجرة المجلدات، و- name يطابق نمطاً. علامة * داخل الاقتباس تمثل عدة أحرف؛ استعمل -type f لحصر الملفات.', 'find parcourt l’arborescence; -name suit un motif et -type f restreint aux fichiers.', 'find walks a directory tree; -name matches a pattern and -type f selects files.'), 'find PATH -type f -name "*.txt"', 'find . -name "*.txt"\ntree', LT('النقطة . تعني المجلد الحالي. ضع النمط بين اقتباسين حتى لا يوسعه Bash قبل وصوله إلى find.', 'Le point signifie le dossier courant; citez le motif pour éviter son expansion préalable.', 'A dot refers to the current directory; quote the glob so Bash does not expand it first.'), LT('find ليس مثل grep: الأول يبحث عن أسماء وخصائص الملفات، والثاني داخل محتواها.', 'find cherche des fichiers; grep cherche du texte à l’intérieur.', 'find searches file paths and metadata; grep searches file contents.'), 'find . -name "*.txt"', ['find', 'tree']);
// BASH · 03 · Text
add('b-text', LT('قراءة جزء من ملف', 'Lire le début et la fin', 'Read portions of a file'), LT('تقرأ السجلات الطويلة من غير عرضها كلها.', 'Lire de gros journaux sans tout afficher.', 'Read long logs without dumping everything.'), LT('cat يطبع الملف كاملاً؛ head أول الأسطر وtail آخرها. الخيار -n يحدد العدد في head وtail.', 'cat affiche tout le fichier; head affiche le début et tail la fin. -n fixe le nombre de lignes.', 'cat prints whole files, head shows first lines and tail last lines. -n sets how many lines.'), 'head -n N FILE | tail -n N FILE', 'head -n 3 logs/app.log\ntail -n 2 logs/app.log', LT('قارن المخرجات: بداية سجل التطبيق قد تختلف عن أحدث الأحداث في نهايته.', 'Comparez les premières et les dernières lignes du journal.', 'Compare the oldest displayed lines with the final log entries.'), LT('tail -f يراقب ملفاً حياً في Linux؛ المختبر لا يحاكي البث المستمر.', 'tail -f suit un fichier vivant, ce que le labo ne simule pas.', 'tail -f follows live updates on Linux; this simulator does not stream live changes.'), 'tail -n 2 logs/app.log', ['cat', 'head', 'tail']);
add('b-text', LT('البحث داخل السجلات', 'Rechercher dans les journaux', 'Search inside logs'), LT('تستخرج الرسائل المهمة باستخدام نص أو نمط.', 'Extraire les messages importants avec des motifs.', 'Extract important messages with text patterns.'), LT('grep يعيد الأسطر المطابقة، -i يتجاهل حالة الأحرف و-n يظهر رقم السطر. rg أداة بحث سريعة في الملفات، لكنها ليست مثبتة في كل توزيع.', 'grep renvoie les lignes trouvées; -i ignore la casse et -n affiche les numéros. rg est un autre moteur de recherche.', 'grep returns matching lines; -i ignores case and -n adds line numbers. rg is another search tool.'), 'grep -n PATTERN FILE | rg PATTERN DIR', 'grep -n ERROR logs/app.log\nrg ERROR logs', LT('استعمل رقم السطر لتحديد مكان الخطأ، وميّز بين البحث في ملف والبحث في مجلد كامل.', 'Les numéros de ligne aident à localiser les erreurs.', 'Line numbers help locate problems; distinguish searching one file from searching a directory.'), LT('الأنماط في grep قد تُفسّر كتعبيرات نمطية، وليست دوماً نصاً حرفياً.', 'Un motif grep peut être une expression régulière, pas uniquement du texte brut.', 'grep patterns can be regular expressions rather than literal text.'), 'grep -n ERROR logs/app.log', ['grep', 'rg']);
add('b-text', LT('الفرز وإزالة التكرار', 'Trier et supprimer les doublons', 'Sort and remove duplicates'), LT('تحوّل قائمة غير مرتبة إلى قيم فريدة.', 'Produire des valeurs uniques à partir d’une liste.', 'Turn a list into unique values.'), LT('sort يرتب الأسطر، أما uniq فيزيل التكرار المتجاور فقط؛ لذلك غالباً تكتب sort | uniq.', 'sort trie les lignes; uniq ne dédoublonne que les lignes adjacentes, donc combinez-les.', 'sort orders lines; uniq removes adjacent duplicates only, so combine sort | uniq.'), 'sort FILE | uniq', 'cat names.txt | sort | uniq', LT('الـPipeline يرسل ناتج sort إلى uniq، فتُجمّع القيم المكررة قبل حذف تكرارها.', 'Le pipeline trie d’abord les lignes, ce qui rend les doublons contigus.', 'Sorting makes duplicates adjacent so uniq can collapse them.'), LT('uniq وحده لن يحذف كل التكرارات من قائمة غير مرتبة.', 'uniq seul ne retire pas tous les doublons d’une liste non triée.', 'uniq alone does not remove all duplicates from unsorted input.'), 'cat names.txt | sort | uniq', ['sort', 'uniq']);
add('b-text', LT('عدّ الأسطر واستخراج الأعمدة', 'Compter et extraire les colonnes', 'Count and extract fields'), LT('تستخدم wc وcut للحصول على ملخص سريع.', 'Utiliser wc et cut pour des résumés rapides.', 'Use wc and cut for quick summaries.'), LT('wc -l يحسب الأسطر، وcut -d يحدد الفاصل و-f يختار حقلاً مرقماً من 1. CSV الذي يحتوي اقتباسات معقدة يحتاج قارئ CSV حقيقياً.', 'wc -l compte les lignes; cut -d définit le séparateur et -f choisit le champ (à partir de 1).', 'wc -l counts lines; cut -d sets a delimiter and -f selects a 1-based field.'), 'wc -l FILE | cut -d, -f2 FILE', 'wc -l names.txt\ncut -d, -f1 data/users.csv', LT('اعرف بنية الملف قبل اختيار الفاصل. cut ليس محللاً كاملاً لصيغ CSV المعقدة.', 'Vérifiez le séparateur; cut n’est pas un parseur CSV complet.', 'Check the delimiter; cut is not a full CSV parser.'), LT('الأسطر الأخيرة غير المنتهية بسطر جديد قد تؤثر على wc -l في Linux.', 'Une dernière ligne sans saut de ligne peut changer le résultat de wc -l.', 'A final line without a newline can affect the line count.'), 'wc -l names.txt', ['wc', 'cut']);
// BASH · 04 · Pipelines
add('b-pipes', LT('كيف يعمل Pipeline؟', 'Comprendre les pipelines', 'How pipelines work'), LT('ترسل stdout لأمر نحو stdin لأمر آخر.', 'Transmettre stdout d’une commande à stdin d’une autre.', 'Send one command’s stdout to the next command’s stdin.'), LT('الرمز | يربط تدفق النص؛ إنه لا يمرر أسماء الملفات تلقائياً. اختبر كل جزء منفرداً قبل تركيب أنبوب طويل.', '| relie les flux texte, pas automatiquement les noms de fichiers. Testez chaque étape séparément.', 'The | operator connects text streams, not file paths automatically. Test each stage alone.'), 'COMMAND1 | COMMAND2 | COMMAND3', 'cat logs/app.log | grep ERROR | wc -l', LT('القراءة ثم تصفية ERROR ثم عد الأسطر: مثال عملي على معالجة تدفق واحد في ثلاث مراحل.', 'Lecture du journal, filtrage ERROR puis comptage des lignes.', 'Read the log, filter ERROR lines, then count matching lines.'), LT('تحويل stdout لا يعني بالضرورة تمرير stderr؛ الأخطاء تحتاج معالجة مستقلة.', 'Le pipeline ne transmet pas forcément stderr; les erreurs sont un flux séparé.', 'Pipes normally pass stdout, not stderr, which is a separate stream.'), 'cat logs/app.log | grep ERROR | wc -l', ['grep', 'wc', 'cat']);
add('b-pipes', LT('حفظ المخرجات في ملف', 'Enregistrer la sortie', 'Redirect output into a file'), LT('تفرق بين > للكتابة و>> للإضافة.', 'Distinguer écrasement et ajout à un fichier.', 'Know the difference between overwrite and append.'), LT('> يكتب stdout في ملف ويستبدل محتواه السابق؛ >> يضيف في النهاية. تنفيذ أمر ناجح لا يعني أن نتيجة الملف صحيحة: اقرأه بعد الحفظ.', '> remplace le contenu et >> ajoute à la fin. Vérifiez le fichier après écriture.', '> overwrites a file; >> appends. Inspect the file afterward to confirm the result.'), 'COMMAND > FILE | COMMAND >> FILE', 'echo first > practice-log.txt\necho second >> practice-log.txt\ncat practice-log.txt', LT('السطر الأول ينشئ أو يستبدل، الثاني يضيف دون إزالة السطر السابق.', 'La première commande crée/remplace, la deuxième ajoute.', 'The first line creates/replaces; the next appends.'), LT('لا تستعمل > مع ملف مهم إلا بعد التأكد من اسمه.', 'Ne redirigez pas avec > vers un fichier important sans vérifier le nom.', 'Do not use > on an important file without checking the target.'), 'echo first > practice-log.txt; echo second >> practice-log.txt', ['echo', 'tee']);
add('b-pipes', LT('عرض وحفظ في نفس الوقت', 'Afficher et sauvegarder avec tee', 'Display and save with tee'), LT('تحتفظ بنسخة من نتيجة الفلترة دون إخفائها من الشاشة.', 'Conserver une copie du résultat tout en l’affichant.', 'Save a result while still displaying it.'), LT('tee يقرأ stdin ويكتبه إلى stdout وملف. مع -a يضيف بدل الاستبدال.', 'tee lit stdin, l’écrit sur stdout et dans un fichier; -a ajoute au fichier.', 'tee consumes stdin and writes it both to stdout and a file; -a appends.'), 'COMMAND | tee FILE', 'grep ERROR logs/app.log | tee errors.txt\ncat errors.txt', LT('لا داعي لتشغيل grep مرتين: النتيجة تُعرض وتُحفظ دفعة واحدة.', 'Une seule exécution affiche et enregistre le résultat filtré.', 'One pipeline both shows and records the filtered result.'), LT('tee بدون -a يستبدل الملف الموجود في العادة.', 'tee sans -a écrase généralement le fichier existant.', 'tee without -a usually overwrites an existing file.'), 'grep ERROR logs/app.log | tee errors.txt', ['tee', 'grep']);
add('b-pipes', LT('التنفيذ المشروط && و||', 'Exécution conditionnelle && et ||', 'Conditional execution with && and ||'), LT('تربط أوامر حسب نجاح أو فشل السابق.', 'Enchaîner selon le succès ou l’échec.', 'Chain commands based on success or failure.'), LT('&& ينفذ التالي عند خروج سابق بكود 0، و|| عند فشله. ; يشغل الأمر اللاحق بغض النظر عن النتيجة.', '&& exécute si la précédente réussit, || en cas d’échec et ; sans condition.', '&& runs on success, || on failure, and ; regardless of the previous exit status.'), 'FIRST && SECOND | FIRST || FALLBACK', 'test -f notes.txt && echo found\ntest -f missing.txt || echo absent', LT('الاختبار الأول ينجح فيطبع found؛ الثاني يفشل فيستخدم المسار البديل.', 'Le premier test réussit, le second exécute son alternative.', 'The first test succeeds; the missing file triggers the fallback.'), LT('لا تخلط هذه العوامل مع | الذي ينقل بيانات بدلاً من التحكم الشرطي.', 'Ne confondez pas ces opérateurs avec | qui transporte des données.', 'Do not confuse control operators with |, which passes data.'), 'test -f notes.txt && echo found', ['test', 'true', 'false']);
// BASH · 05 · Data
add('b-data', LT('قراءة CSV بشكل مبدئي', 'Première lecture de CSV', 'Reading simple CSV'), LT('تستخرج الأعمدة من بيانات مفصولة بفواصل.', 'Extraire des colonnes de données simples.', 'Extract fields from simple comma-delimited data.'), LT('CSV صيغة صفوف وأعمدة. cut مناسب لبيانات بسيطة، بينما وجود فاصلة داخل خانة مقتبسة يحتاج أداة CSV تفهم الاقتباس.', 'CSV contient des lignes et colonnes. cut suffit pour des cas simples, pas les cellules citées contenant des virgules.', 'CSV contains rows and columns. cut works for simple files but not quoted fields containing commas.'), 'cut -d, -f1 DATA.csv', 'cat data/users.csv\ncut -d, -f1 data/users.csv', LT('ابدأ بعرض السطر الأول لفهم أسماء الأعمدة، ثم اختر العمود المطلوب.', 'Regardez l’en-tête du fichier avant d’extraire un champ.', 'Inspect the header before selecting a field.'), LT('لا تحلل CSV حقيقياً معقداً بـcut وحده.', 'Ne traitez pas du CSV complexe avec cut seul.', 'Do not parse complicated real CSV with cut alone.'), 'cut -d, -f1 data/users.csv', ['cut', 'awk']);
add('b-data', LT('تحليل أعمدة باستخدام awk', 'Analyser des colonnes avec awk', 'Process columns with awk'), LT('تستعمل awk للقراءة الحقلية والتحويل السريع.', 'Utiliser awk pour un traitement orienté colonnes.', 'Use awk for field-oriented text processing.'), LT('awk يقسم كل سطر إلى حقول، و$1 يعني الأول وNR رقم السطر. الخيار -F يغيّر الفاصل الافتراضي.', 'awk découpe chaque ligne en champs; $1 est le premier et NR le numéro de ligne. -F définit le séparateur.', 'awk splits lines into fields; $1 is first field, NR is row number, and -F sets the separator.'), "awk -F, '{print $1}' FILE", "awk -F, '{print $1}' data/users.csv", LT('صيغة print داخل الأقواس تتكرر لكل سطر؛ هذا مثال بسيط لا يغطي لغة awk بكاملها.', 'L’action print est exécutée pour chaque ligne; il ne s’agit que d’une petite partie de awk.', 'The print action executes on each record; this is only a small subset of awk.'), LT('لا تخلط $1 في awk بمعاملات سكربت Bash من خارج تعبير awk.', 'Le $1 interne à awk n’est pas le paramètre $1 d’un script Bash.', 'awk’s $1 is not the same as the shell script’s $1.'), "awk -F, '{print $1}' data/users.csv", ['awk', 'cut']);
add('b-data', LT('التعامل مع JSON بواسطة jq', 'Lire JSON avec jq', 'Query JSON with jq'), LT('تقرأ قيمة من كائن JSON وتتحقق من شكل البيانات.', 'Lire un champ JSON et comprendre sa structure.', 'Read a field from JSON and understand its structure.'), LT('JSON يحتوي كائنات { } ومصفوفات [ ]. jq يقرأ JSON باستعلام مثل .name أو .items[].name. المختبر يحاكي جزءاً محدوداً من jq.', 'JSON comporte objets et tableaux. jq permet .name ou .items[].name; le labo n’en simule qu’une partie.', 'JSON has objects and arrays. jq supports selectors like .name and .items[].name; the lab implements a subset.'), 'jq .name DATA.json | jq -r .name DATA.json', 'cat data/config.json\njq .name data/config.json', LT('النقطة تعني جذر بيانات JSON، وname خاصية موجودة في هذا الجذر.', 'Le point désigne la racine et name une propriété de l’objet.', 'The dot means the root value and name refers to a property on it.'), LT('JSON غير الصحيح أو اسم خاصية غير موجودة قد يعطي خطأ أو null.', 'Un JSON mal formé ou un champ absent peut provoquer une erreur ou null.', 'Malformed JSON or a missing field can yield an error or null.'), 'jq .name data/config.json', ['jq']);
add('b-data', LT('مقارنة نسختين من ملف', 'Comparer deux versions', 'Compare two file versions'), LT('تحدد الأسطر التي تغيّرت بين تقريرين.', 'Identifier les lignes modifiées entre deux fichiers.', 'Find changed lines between two versions.'), LT('diff يعرض الاختلافات بين ملفين نصيين؛ cmp يخبرك إن كان المحتوى متطابقاً أو أين يبدأ الفرق.', 'diff présente les différences textuelles; cmp vérifie l’identité et localise le premier écart.', 'diff shows text differences; cmp checks byte-level equality or the first mismatch.'), 'diff FILE1 FILE2 | cmp FILE1 FILE2', 'cp notes.txt version-a.txt\necho new > version-b.txt\ndiff version-a.txt version-b.txt', LT('ابدأ بملفين مختلفين لترى أن diff ليس أداة دمج وإنما أداة مقارنة.', 'Deux fichiers différents permettent d’observer que diff compare mais ne fusionne pas.', 'Use two different files to see that diff compares rather than merges.'), LT('مخرجات diff غير الفارغة ليست دائماً فشلاً؛ قد تعني وجود فروق.', 'Une sortie non vide de diff peut simplement signaler des différences.', 'Nonempty diff output usually signals differences, not necessarily an unexpected failure.'), 'diff notes.txt names.txt', ['diff', 'cmp']);
// BASH · 06 · System
add('b-system', LT('هوية المستخدم وامتيازاته', 'Identité et privilèges', 'User identity and privileges'), LT('تتعرف على الحساب الحالي والمجموعات.', 'Identifier l’utilisateur et ses groupes.', 'Identify the user and their groups.'), LT('whoami يعرض اسم المستخدم وid معلومات UID وGID. لا تحتاج صلاحيات root لمعظم أوامر القراءة والتدريب.', 'whoami affiche le compte et id donne UID/GID. La lecture et l’entraînement ne nécessitent généralement pas root.', 'whoami shows the account and id shows UID/GID. Most read-only practice does not require root.'), 'whoami | id | groups', 'whoami\nid\ngroups', LT('قارن اسم الحساب مع رقم UID والمجموعات؛ إنها مفاهيم مختلفة في الصلاحيات.', 'Comparez compte, UID et groupes : ils servent à des notions différentes d’autorisation.', 'Compare username, UID and groups: they describe different identity attributes.'), LT('تجنب sudo لأي أمر لم تفهم تأثيره على جهاز حقيقي.', 'Évitez sudo pour une commande dont vous ne comprenez pas l’effet.', 'Avoid sudo for commands whose effects you do not understand.'), 'id', ['whoami', 'id', 'groups']);
add('b-system', LT('فهم صلاحيات الملفات', 'Comprendre les permissions', 'Understand file permissions'), LT('تقرأ رموز r وw وx وعلاقتها بالمالك والمجموعة والآخرين.', 'Lire r, w, x pour propriétaire, groupe et autres.', 'Read r, w and x for owner, group and others.'), LT('في ls -l هناك ثلاث مجموعات صلاحيات: المستخدم والمجموعة والآخرون. chmod يغيرها في النظام الحقيقي؛ لا يمنح صلاحية فوق ما يسمح به النظام.', 'Dans ls -l, les permissions concernent propriétaire, groupe et autres. chmod les modifie avec les droits requis.', 'ls -l lists permissions for owner, group and others. Real chmod changes mode bits, subject to permissions.'), 'ls -l FILE | chmod MODE FILE', 'ls -l notes.txt', LT('اقرأ العرض أولاً: r للقراءة، w للكتابة، x للتنفيذ. هذا درس فهم وليس دعوة لتغيير صلاحيات النظام.', 'Lisez r (lecture), w (écriture), x (exécution) avant toute modification.', 'Interpret r (read), w (write) and x (execute) before changing anything.'), LT('chmod 777 على الملفات الحساسة يمنح صلاحيات أكثر من اللازم.', 'Évitez chmod 777 sur les fichiers sensibles : trop permissif.', 'chmod 777 is usually overly permissive for sensitive files.'), 'ls -l notes.txt', ['ls', 'chmod', 'stat']);
add('b-system', LT('فحص العمليات', 'Observer les processus', 'Inspect processes'), LT('تميّز بين PID والأمر والعملية الجارية.', 'Lire PID, commande et état d’un processus.', 'Distinguish PID, command and running process.'), LT('ps يعرض عمليات، وtop/htop قد يعرضان حالة متغيرة. قتل عملية يحتاج فهم هويتها وتأثير توقفها.', 'ps liste des processus; top/htop suivent leur évolution. Il faut identifier une cible avant toute interruption.', 'ps lists processes; top/htop show changing state. Identify a process before attempting to stop it.'), 'ps aux | ps -ef', 'ps', LT('PID معرّف يتغير بمرور الوقت، فلا تعتمد على رقم محفوظ من تشغيل سابق.', 'Un PID peut changer : ne réutilisez pas un ancien numéro à l’aveugle.', 'PIDs can change: do not blindly reuse an old process ID.'), LT('العمليات المعروضة في المختبر نماذج وليست عمليات جهازك.', 'Les processus du labo sont des exemples, pas ceux de l’ordinateur réel.', 'Lab processes are samples, not your computer’s real processes.'), 'ps', ['ps', 'top', 'kill']);
add('b-system', LT('معرفة استهلاك التخزين', 'Surveiller disque et mémoire', 'Inspect storage and memory'), LT('تفهم الفرق بين مساحة القرص وحجم المجلد والذاكرة.', 'Distinguer stockage, taille des dossiers et mémoire.', 'Distinguish disk capacity, directory size and memory.'), LT('df -h يعطي سعة الأنظمة المركّبة، du -sh يحسب الحجم التقريبي لمجلد، وfree -h يعرض الذاكرة.', 'df -h montre les systèmes de fichiers, du -sh l’espace d’un dossier, free -h la mémoire.', 'df -h shows filesystem space, du -sh directory usage and free -h memory.'), 'df -h | du -sh DIR | free -h', 'df -h\ndu -sh Documents\nfree -h', LT('قد يكون df وdu مختلفين بسبب ملفات محذوفة مفتوحة أو ملفات مشتركة.', 'df et du peuvent différer à cause des fichiers ouverts ou du fonctionnement du système.', 'df and du can disagree because of open deleted files or filesystem details.'), LT('الأرقام في المختبر ثابتة أو افتراضية ولا تمثل قرصك الحقيقي.', 'Les valeurs du labo sont simulées et ne décrivent pas votre disque.', 'Lab values are simulated, not actual device measurements.'), 'du -sh Documents', ['df', 'du', 'free']);
// BASH · 07 · Network
add('b-network', LT('قراءة عنوان IP', 'Lire les adresses IP', 'Inspect IP addresses'), LT('تعرف ما هو IP والقناع والواجهة.', 'Comprendre adresse, masque et interface.', 'Understand addresses, prefixes and interfaces.'), LT('ip addr يعرض عناوين الواجهات، وip route يوضح مسارات الوصول. عنوان IPv4 ليس منفذاً؛ والمنفذ خاص بخدمة النقل.', 'ip addr montre les adresses; ip route montre le routage. Une adresse IP n’est pas un port.', 'ip addr shows interface addresses; ip route shows routes. An IP address is not a transport port.'), 'ip addr | ip route', 'ip addr', LT('اقرأ عنواناً مثل 192.0.2.10/24 على أنه عنوان مع طول بادئة، وليس عنوان جهاز حقيقي في المختبر.', '192.0.2.10/24 associe adresse et longueur du préfixe; c’est une donnée d’exemple.', '192.0.2.10/24 is an address and prefix length, used here as a sample.'), LT('لا تستخدم أمثلة IP الوهمية لتهيئة شبكة حقيقية.', 'N’appliquez pas des adresses fictives à un réseau réel.', 'Do not configure a real network using the simulated sample addresses.'), 'ip addr', ['ip', 'route']);
add('b-network', LT('المنافذ والاتصالات', 'Ports et connexions', 'Ports and sockets'), LT('تقرأ حالات الاتصال والخدمات المستمعة.', 'Lire les connexions et les services en écoute.', 'Read connections and listening services.'), LT('ss يعرض مقابس الشبكة؛ -t TCP و-u UDP و-l تعني الاستماع. ليس كل منفذ ظاهر في ss مفتوحاً للعالم الخارجي.', 'ss liste les sockets; -t TCP, -u UDP, -l écoute. Une écoute locale n’implique pas une exposition publique.', 'ss lists sockets: -t TCP, -u UDP, -l listening. A local listener is not necessarily reachable publicly.'), 'ss -tuln', 'ss -tuln', LT('راجع العنوان المحلي ورقم المنفذ والحالة، ولا تستنتج حالة جدار الحماية من ss وحده.', 'Regardez l’adresse locale, le port et l’état; ss ne remplace pas un test de pare-feu.', 'Read local address, port and state; ss alone does not prove firewall reachability.'), LT('المنفذ 0.0.0.0 يعني ربطاً على كل واجهات IPv4 محلياً، وليس إثباتاً أنه متاح عبر الإنترنت.', '0.0.0.0 signifie toutes les interfaces locales IPv4, pas une exposition Internet garantie.', '0.0.0.0 binds local IPv4 interfaces; it does not guarantee internet exposure.'), 'ss -tuln', ['ss', 'netstat']);
add('b-network', LT('DNS مقابل الاتصال بالشبكة', 'DNS et connectivité', 'DNS versus connectivity'), LT('تفرق بين حل الاسم ونجاح الاتصال.', 'Différencier résolution DNS et accessibilité réseau.', 'Separate DNS resolution from network reachability.'), LT('dig يحاول معرفة سجلات DNS، وping يختبر استجابة ICMP. عدم الرد على ping قد يكون بسبب حظر ICMP وليس انقطاع الإنترنت.', 'dig interroge le DNS; ping teste ICMP. Une absence de réponse n’est pas une preuve d’absence de connexion.', 'dig queries DNS; ping tests ICMP. A missing ping reply may just mean ICMP is filtered.'), 'dig example.com | ping -c 2 127.0.0.1', 'dig example.com\nping -c 2 127.0.0.1', LT('الاختبارات في المختبر تستخدم مخرجات افتراضية ولا تجري استعلامات شبكة فعلية.', 'Dans ce labo, les résultats sont simulés et aucune requête réseau réelle n’a lieu.', 'In this lab outputs are simulated and no real network request is made.'), LT('لا تعتبر حل اسم DNS دليلاً على أن خدمة HTTP متوفرة.', 'La résolution DNS seule ne garantit pas qu’un site HTTP fonctionne.', 'Successful DNS resolution does not prove an HTTP service is working.'), 'dig example.com', ['dig', 'ping']);
add('b-network', LT('تشخيص HTTP والسجلات', 'Diagnostiquer HTTP et journaux', 'Diagnose HTTP and logs'), LT('تربط أخطاء التطبيقات بمراحل طلب الشبكة.', 'Associer les erreurs aux étapes d’une requête.', 'Relate application errors to request phases.'), LT('curl أداة عميل HTTP وغيرها؛ -I يطلب الترويسات. افحص DNS ثم TCP ثم HTTP ثم سجلات التطبيق بدلاً من تغيير إعدادات عشوائياً.', 'curl est un client HTTP; -I demande les en-têtes. Diagnostic : DNS, TCP, HTTP puis journaux.', 'curl is an HTTP client; -I requests headers. Troubleshoot DNS, TCP, HTTP, then application logs.'), 'curl -I URL | grep ERROR LOG', 'curl -I https://example.com\ngrep ERROR logs/app.log', LT('المختبر لا يتصل بالموقع؛ curl فيه يعرض مثالاً تعليمياً فقط.', 'Le curl du labo affiche un exemple; il ne contacte pas le site.', 'The lab’s curl output is a teaching sample, not a network request.'), LT('لا تضع كلمات مرور أو رموز API في أوامر مسجلة في History.', 'Évitez les mots de passe et jetons API dans l’historique du shell.', 'Do not expose passwords or API tokens in shell history.'), 'grep ERROR logs/app.log', ['curl', 'grep']);
// BASH · 08 · Automation
add('b-automation', LT('متغيرات البيئة والمتغيرات العادية', 'Variables et environnement', 'Variables and environment'), LT('تنشئ متغيراً وتفهم دور export.', 'Créer une variable et comprendre export.', 'Set a variable and understand export.'), LT('NAME=value يحدد متغيراً في Bash؛ export يسمح بتمريره إلى البرامج الفرعية. لا تضع مسافات حول = في التعيين.', 'NAME=value définit une variable; export la transmet aux sous-processus. Pas d’espace autour de =.', 'NAME=value assigns a variable; export makes it available to child processes. Do not put spaces around =.'), 'NAME=value | export NAME=value', 'export TEAM=network\necho "$TEAM"\nprintenv TEAM', LT('يطبع echo القيمة بعد توسيع المتغير؛ printenv يقرأ متغيرات البيئة المصدّرة.', 'echo affiche l’expansion et printenv lit l’environnement exporté.', 'echo expands the variable; printenv reads exported environment values.'), LT('لا تخزن كلمات مرور حساسة كمتغيرات ظاهرة في الأوامر أو سجلها.', 'Évitez les secrets dans les commandes enregistrées ou visibles.', 'Avoid storing secrets in visible or logged commands.'), 'export TEAM=network; echo "$TEAM"', ['export', 'printenv', 'env']);
add('b-automation', LT('الشروط وExit Status', 'Conditions et code de sortie', 'Conditions and exit status'), LT('تفهم معنى true/false وif في السكربتات.', 'Comprendre true/false et if en script.', 'Understand true/false and if in scripts.'), LT('كل أمر يعيد كود خروج: 0 يعني نجاحاً عادةً. if يفحص كود الخروج أو شرط test، وليس مجرد وجود نص في stdout.', 'Un code de sortie 0 signifie habituellement réussite. if examine le statut, pas la présence de texte.', 'Exit code 0 typically means success. if checks status, not merely whether text was printed.'), 'if test -f FILE; then echo yes; else echo no; fi', 'test -f notes.txt && echo yes', LT('الاختبار البسيط في المختبر يستخدم &&؛ صيغة if الكاملة موضحة لفهم سكربت Bash الحقيقي.', 'Le labo utilise && dans cet exemple; la forme if complète concerne un vrai script Bash.', 'The lab uses && for this example; the full if structure is for real Bash scripts.'), LT('اكتب مسافات حول [ ] في صيغة [ -f file ] التقليدية.', 'La forme [ -f file ] exige des espaces autour des crochets.', 'Traditional [ -f file ] syntax requires spaces around the brackets.'), 'test -f notes.txt && echo yes', ['test', 'true', 'false']);
add('b-automation', LT('التكرار والحلقات', 'Boucles et itérations', 'Loops and iteration'), LT('تستعمل for لتكرار عملية على مجموعة صغيرة.', 'Parcourir plusieurs valeurs avec for.', 'Use for to repeat work over a short list.'), LT('الحلقات تنفذ الجسم لكل قيمة. في الملفات الحقيقية استعمل اقتباس المتغير لتفادي تفكيك المسارات ذات الفراغات.', 'Les boucles exécutent le bloc pour chaque valeur; citez les variables contenant des chemins.', 'Loops repeat the body for each value; quote filename variables to preserve spaces.'), 'for x in one two; do echo "$x"; done', 'seq 1 4', LT('يعرض seq تسلسلاً في المختبر؛ حلقة for الكاملة مثال على Bash الحقيقي وقد لا تعمل في المحاكي.', 'seq illustre une suite dans le labo; for complet est une syntaxe de Bash réel.', 'seq demonstrates sequences in the lab; full for-loop syntax needs a real Bash shell.'), LT('لا تفترض أن for f in * آمن إذا احتوت أسماء الملفات فراغات أو أنماطاً غير متوقعة.', 'Les noms avec espaces ou caractères spéciaux exigent des précautions.', 'File names with spaces or special characters require care.'), 'seq 1 4', ['seq', 'for']);
add('b-automation', LT('كتابة سكربت Bash قابل للصيانة', 'Écrire un script Bash maintenable', 'Write a maintainable Bash script'), LT('تجمع الأوامر في ملف وتتحقق من الإدخال.', 'Regrouper des commandes et vérifier les entrées.', 'Put commands in a file and validate input.'), LT('يبدأ السكربت عادة بـ#!/usr/bin/env bash، ويُنفذ بـbash file.sh حتى دون chmod +x. افصل المدخلات عن منطق المعالجة، واختبر على بيانات غير مهمة.', 'Un script commence souvent par #!/usr/bin/env bash et se lance avec bash file.sh. Validez les entrées et testez sur des données de labo.', 'A script often begins with #!/usr/bin/env bash and can run as bash file.sh. Validate inputs and test on disposable data.'), '#!/usr/bin/env bash\nset -e\necho "ready"', 'echo ready\nwhoami', LT('هذا مثال تعليمي على بنية السكربت؛ HTML لا يشغّل سكربت Bash حقيقياً ولا يدعم كل بناءات اللغة.', 'C’est un exemple de structure : HTML n’exécute pas un vrai script Bash et le labo ne gère pas tout le langage.', 'This illustrates script structure; HTML cannot execute real Bash scripts and the simulator only supports a subset.'), LT('set -e ليس بديلاً شاملاً عن التحقق من الأخطاء؛ له استثناءات في بعض السياقات.', 'set -e comporte des exceptions et ne remplace pas une gestion explicite des erreurs.', 'set -e has exceptions and is not a substitute for thoughtful error handling.'), 'echo ready', ['bash', 'chmod', 'echo']);
// POWERSHELL · 01 · Foundations
add('p-start', LT('ما هو PowerShell؟', 'Comprendre PowerShell', 'What is PowerShell?'), LT('تفهم Cmdlet والفرق بين النص والكائن.', 'Comprendre les cmdlets et les objets.', 'Understand cmdlets and objects.'), LT('PowerShell صدفة ولغة أتمتة. أسماء Cmdlets غالباً Verb-Noun مثل Get-Process، وPipeline يمرر كائنات تحتوي خصائص.', 'PowerShell est un shell et langage d’automatisation; ses cmdlets ressemblent à Verb-Noun et transmettent des objets.', 'PowerShell is a shell and automation language. Cmdlets commonly use Verb-Noun naming and pass rich objects.'), 'Get-Command | Get-Location | Get-Process', 'Get-Location\nGet-Process | Select-Object -First 3', LT('Get-Location يعرض المسار، وGet-Process يقدم كائنات عمليات وليس مجرد أسطر نصية.', 'Get-Location donne le chemin et Get-Process renvoie des objets processus.', 'Get-Location displays the path and Get-Process returns process objects.'), LT('لا تفترض أن كل أمر شائع على Windows يتوفر بنفس الشكل على Linux.', 'La disponibilité varie selon Windows, Linux et les modules installés.', 'Cmdlet availability differs by OS and installed modules.'), 'Get-Location', ['Get-Location', 'Get-Process']);
add('p-start', LT('كيف تقرأ Get-Help؟', 'Lire Get-Help', 'Read Get-Help'), LT('تقرأ Syntax والمعاملات وأمثلة الاستخدام.', 'Lire syntaxe, paramètres et exemples.', 'Read syntax, parameters and examples.'), LT('Get-Help Command -Examples يستعرض أمثلة، و-Full تفصيل أكبر في نسخة حقيقية مكتملة المساعدة. قد تحتاج تحديث ملفات المساعدة على جهازك.', 'Get-Help Command -Examples donne des exemples; -Full est plus détaillé si l’aide est disponible.', 'Get-Help Command -Examples displays examples and -Full gives expanded help when installed.'), 'Get-Help NAME -Examples | Get-Help NAME -Full', 'Get-Help Get-Process\nGet-Command', LT('افهم المعاملات المسماة قبل نسخ أوامر إدارية إلى جهاز حقيقي.', 'Lisez les paramètres avant de copier des commandes administratives.', 'Understand parameters before running administrative commands on a real machine.'), LT('في المحاكي معلومات Get-Help محدودة؛ راجع PowerShell المثبت عندك للتوثيق الكامل.', 'L’aide du simulateur est réduite : consultez celle de votre installation.', 'Simulator help is limited; use your installed PowerShell for full documentation.'), 'Get-Help Get-Process', ['Get-Help', 'Get-Command']);
add('p-start', LT('اكتشاف الأوامر والـAliases', 'Découvrir commandes et alias', 'Discover commands and aliases'), LT('تستعمل Get-Command وGet-Alias لفهم الأسماء.', 'Trouver des commandes et alias.', 'Find commands and aliases.'), LT('Get-Command يعرض الأوامر المتاحة وGet-Alias أسماء مختصرة مثل ls أو dir. الاسم المختصر قد يختلف باختلاف نظام التشغيل والملف الشخصي.', 'Get-Command découvre les commandes; Get-Alias révèle les alias comme ls ou dir. Ils varient selon l’environnement.', 'Get-Command discovers commands and Get-Alias resolves shortcuts such as ls and dir; aliases can vary.'), 'Get-Command | Get-Alias', 'Get-Command\nGet-Alias', LT('في سكربت مهني يستحسن استخدام الاسم الكامل للـCmdlet حتى يكون واضحاً.', 'Dans un script partagé, préférez le nom complet de la cmdlet.', 'Prefer full cmdlet names in shared scripts for clarity.'), LT('لا تتوقع من ls في PowerShell نفس جميع خيارات GNU ls في Bash.', 'L’alias ls PowerShell n’implique pas les options GNU ls.', 'PowerShell’s ls alias does not imply GNU ls flag compatibility.'), 'Get-Alias', ['Get-Alias', 'Get-Command']);
add('p-start', LT('المسارات ومزوّد الملفات', 'Chemins et fournisseur fichiers', 'Paths and providers'), LT('تتعرف على Get-Location وSet-Location والمسارات.', 'Utiliser Get-Location et Set-Location.', 'Use Get-Location and Set-Location.'), LT('PowerShell يتعامل مع المسارات عبر Providers مثل FileSystem، ويمكنه أيضاً العمل على Provider للمتغيرات والشهادات والتسجيل في بيئات معينة.', 'PowerShell accède aux chemins via des providers, notamment FileSystem et d’autres selon la plateforme.', 'PowerShell accesses paths through providers including FileSystem and others depending on the platform.'), 'Get-Location | Set-Location PATH', 'Get-Location\nGet-ChildItem\nSet-Location Documents\nGet-Location', LT('التغيير يؤثر على جلسة المحاكاة فقط. استعمل -LiteralPath عند التعامل مع محارف wildcard في الملف الحقيقي.', 'Le changement ne concerne que cette session virtuelle. -LiteralPath traite les noms spéciaux littéralement.', 'The change affects only the virtual session. -LiteralPath helps treat wildcard characters literally in real PowerShell.'), LT('المسارات C:\ مثال Windows؛ على Linux تختلف الجذور والشرطة المائلة.', 'C:\ est typique de Windows; les chemins Linux diffèrent.', 'C:\ is Windows-style; Linux uses different path roots.'), 'Get-Location', ['Get-Location', 'Set-Location', 'Get-ChildItem']);
// POWERSHELL · 02 · Files
add('p-files', LT('استعراض المجلدات', 'Explorer les dossiers', 'List directories'), LT('تستعمل Get-ChildItem وعوامل التصفية.', 'Utiliser Get-ChildItem et ses filtres.', 'Use Get-ChildItem and filters.'), LT('Get-ChildItem يعرض العناصر؛ -Recurse يضم المجلدات الفرعية و-File يختار الملفات في PowerShell الحقيقي.', 'Get-ChildItem énumère les éléments; -Recurse inclut les sous-dossiers et -File choisit les fichiers.', 'Get-ChildItem lists items, -Recurse includes descendants and -File filters files in real PowerShell.'), 'Get-ChildItem -Path PATH -Recurse', 'Get-ChildItem\nGet-ChildItem Documents', LT('ابدأ بغير -Recurse كي تكتشف الحجم وعدد العناصر قبل البحث الشامل.', 'Commencez sans -Recurse pour évaluer la taille de l’arborescence.', 'Start without -Recurse so you understand the scope first.'), LT('المسح الواسع قد يكون بطيئاً على ملفات كثيرة أو مشاركات شبكة.', 'Une énumération récursive peut être lente sur de grands volumes.', 'Recursive listing can be slow on large trees or network shares.'), 'Get-ChildItem Documents', ['Get-ChildItem']);
add('p-files', LT('إنشاء ملفات ومجلدات', 'Créer fichiers et dossiers', 'Create files and folders'), LT('تنشئ ملفات بواسطة New-Item.', 'Créer avec New-Item.', 'Create items with New-Item.'), LT('New-Item -ItemType Directory ينشئ مجلداً، و-ItemType File ينشئ ملفاً. استعمل -Path لتحديد المكان بوضوح.', 'New-Item -ItemType Directory crée un dossier, et File crée un fichier. -Path précise l’emplacement.', 'New-Item -ItemType Directory creates a directory and File creates a file. -Path chooses its location.'), 'New-Item -Path PATH -ItemType File|Directory', 'New-Item -Path lessons -ItemType Directory\nNew-Item -Path lessons/task.txt -ItemType File', LT('نفذ الأمر الأول قبل الثاني لوجود المجلد الأب، ثم اعرض المحتوى.', 'Créez d’abord le dossier parent, puis le fichier.', 'Create the parent directory first, then the file.'), LT('قد يحتاج استبدال ملف موجود إلى -Force؛ تحقّق قبل استخدامه.', '-Force peut remplacer des données : vérifiez avant de l’utiliser.', '-Force can affect existing items; inspect before using it.'), 'New-Item -Path lessons -ItemType Directory', ['New-Item', 'Test-Path']);
add('p-files', LT('نسخ العناصر ونقلها', 'Copier et déplacer', 'Copy and move items'), LT('تستعمل Copy-Item وMove-Item وتحدد المصدر والوجهة.', 'Employer Copy-Item et Move-Item.', 'Use Copy-Item and Move-Item.'), LT('Copy-Item يصنع نسخة، أما Move-Item فيغير موقع العنصر. -Recurse مطلوب عادة لنسخ مجلد مع محتوياته.', 'Copy-Item copie et Move-Item déplace; -Recurse est habituellement nécessaire pour copier une arborescence.', 'Copy-Item duplicates and Move-Item relocates items; directory trees generally require -Recurse for copying.'), 'Copy-Item SRC DEST | Move-Item SRC DEST', 'Copy-Item notes.txt copy.txt\nMove-Item copy.txt final.txt\nGet-ChildItem', LT('نفذ الخطوتين وشاهد كيف يبقى الأصل بعد النسخ ثم يتغير اسم النسخة.', 'La source reste après la copie; seule la copie est ensuite déplacée.', 'The source survives copying while the copied file changes name.'), LT('تأكد من أن الوجهة ليست ملفاً مهماً سيُستبدل.', 'Contrôlez que la cible n’est pas un fichier important.', 'Ensure the destination is not an important existing file.'), 'Copy-Item notes.txt copy.txt', ['Copy-Item', 'Move-Item']);
add('p-files', LT('التحقق قبل الحذف', 'Vérifier avant suppression', 'Check before deletion'), LT('تتأكد من وجود مسار قبل أي تعديل.', 'Vérifier l’existence avant modification.', 'Check existence before modifying files.'), LT('Test-Path يعيد True أو False. Remove-Item يحذف عناصر، و-Recurse يسمح بحذف المجلدات المتداخلة. استخدم -WhatIf في PowerShell الحقيقي للأوامر التي تدعمه.', 'Test-Path renvoie True/False; Remove-Item supprime. -WhatIf peut montrer les effets pour les commandes qui le prennent en charge.', 'Test-Path returns Boolean results; Remove-Item deletes items. -WhatIf previews effects for supported real cmdlets.'), 'Test-Path PATH | Remove-Item PATH -WhatIf', 'Test-Path notes.txt\nTest-Path missing.txt', LT('اختبر المسار أولاً، ثم راجع الوسائط. المختبر لا يغيّر ملفات جهازك.', 'Vérifiez le chemin et les paramètres. Le labo ne modifie pas votre disque.', 'Check the path and arguments. The lab cannot modify your actual drive.'), LT('لا تفترض أن -WhatIf مدعوم في كل برنامج أو Alias خارجي.', '-WhatIf n’est pas universel : vérifiez la documentation.', '-WhatIf is not universally supported; check each command.'), 'Test-Path notes.txt', ['Test-Path', 'Remove-Item']);
// POWERSHELL · 03 · Content
add('p-content', LT('قراءة الملفات بالنص', 'Lire le contenu texte', 'Read text files'), LT('تقرأ كامل المحتوى أو أول الأسطر.', 'Lire le contenu ou une partie.', 'Read full content or selected lines.'), LT('Get-Content يعيد الأسطر إلى Pipeline، و-TotalCount يحدد عدد الأسطر الأولى في PowerShell الحقيقي.', 'Get-Content transmet les lignes au pipeline; -TotalCount limite le nombre de lignes.', 'Get-Content sends lines down the pipeline; -TotalCount limits how many are read from the start.'), 'Get-Content FILE | Get-Content FILE -TotalCount 5', 'Get-Content notes.txt\nGet-Content logs/app.log', LT('تميّز بين الحصول على نص وقراءة كائنات لها خصائص مستقلة.', 'Le contenu textuel n’est pas toujours un objet métier structuré.', 'Text file lines are not the same as domain objects with named fields.'), LT('قد يكون ترميز الملف مختلفاً؛ تحقق من -Encoding عند ظهور نص مشوه.', 'En cas de texte illisible, vérifiez l’encodage.', 'If text looks corrupted, inspect the encoding.'), 'Get-Content notes.txt', ['Get-Content']);
add('p-content', LT('البحث عن كلمة أو نمط', 'Rechercher avec Select-String', 'Search with Select-String'), LT('تبحث داخل ملف أو داخل Pipeline.', 'Chercher dans un fichier ou pipeline.', 'Search files or pipeline text.'), LT('Select-String يرجع معلومات مطابقة تتضمن السطر ورقمه في PowerShell الحقيقي. وقد يستعمل Regex، لذلك احذر من محارف خاصة.', 'Select-String renvoie des correspondances contenant ligne et numéro; les motifs peuvent être des regex.', 'Select-String returns match information including matching line numbers; patterns may be regex.'), 'Get-Content FILE | Select-String PATTERN', 'Get-Content logs/app.log | Select-String ERROR', LT('اقرأ السجل ثم صفّه حسب النص المطلوب، وتحقق من الأسطر الراجعة.', 'Lisez le journal et filtrez les lignes contenant le motif.', 'Read the log and filter it for the desired text.'), LT('لا تفترض أن Select-String وgrep متطابقان في المعاملات ونوع المخرجات.', 'Select-String et grep diffèrent en paramètres et types de sortie.', 'Select-String and grep differ in parameters and output types.'), 'Get-Content logs/app.log | Select-String ERROR', ['Select-String', 'Get-Content']);
add('p-content', LT('كتابة المحتوى وإضافته', 'Écrire et ajouter du contenu', 'Write and append content'), LT('تميّز بين Set-Content وAdd-Content.', 'Distinguer Set-Content de Add-Content.', 'Distinguish Set-Content and Add-Content.'), LT('Set-Content يستبدل محتوى الملف، وAdd-Content يضيف بيانات إلى نهايته. -Value يحدد المحتوى المكتوب.', 'Set-Content remplace le contenu; Add-Content ajoute à la fin. -Value précise les données.', 'Set-Content replaces file content and Add-Content appends; -Value supplies the text.'), 'Set-Content FILE -Value TEXT | Add-Content FILE -Value TEXT', 'Set-Content -Path message.txt -Value first\nAdd-Content -Path message.txt -Value second\nGet-Content message.txt', LT('النتيجة تحتوي السطرين؛ لو استعملت Set-Content مرتين فلن تبقى القيمة الأولى.', 'Les deux valeurs restent; deux Set-Content successifs auraient remplacé la première.', 'Both values remain; repeating Set-Content instead would replace the first.'), LT('الكتابة إلى ملف في مسار محمي تحتاج صلاحيات مناسبة في النظام الحقيقي.', 'Les chemins protégés nécessitent des permissions sur le système réel.', 'Protected real paths require appropriate permissions.'), 'Set-Content -Path message.txt -Value first', ['Set-Content', 'Add-Content']);
add('p-content', LT('حفظ مخرجات الأوامر', 'Enregistrer la sortie des commandes', 'Save command output'), LT('تختار بين Out-File وOut-String وTee-Object.', 'Choisir Out-File, Out-String et Tee-Object.', 'Choose Out-File, Out-String and Tee-Object.'), LT('Out-File يكتب تمثيلاً نصياً للنتيجة، وOut-String يحول العرض إلى نص، وTee-Object يعرض النتيجة ويحفظ نسخة.', 'Out-File écrit du texte formaté, Out-String convertit en chaîne et Tee-Object garde une copie.', 'Out-File writes text, Out-String converts formatted output to text, and Tee-Object saves a copy.'), 'Get-Process | Select-Object Name | Out-File processes.txt', 'Get-Process | Select-Object Name | Out-File processes.txt\nGet-Content processes.txt', LT('عند إعادة قراءة الملف تحصل على نص، وليس كائنات العمليات الأصلية.', 'À la relecture vous obtenez du texte, pas les objets processus d’origine.', 'When rereading the file you get text, not the original process objects.'), LT('استخدم Export-Csv أو ConvertTo-Json إذا كنت تريد حفظ بيانات منظمة قابلة للاستيراد.', 'Préférez Export-Csv ou JSON pour conserver les données structurées.', 'Use Export-Csv or JSON when you need structured, re-importable data.'), 'Get-Process | Select-Object Name | Out-File processes.txt', ['Out-File', 'Tee-Object', 'Out-String']);
// POWERSHELL · 04 · Objects
add('p-objects', LT('اكتشاف خصائص الكائنات', 'Explorer les propriétés des objets', 'Inspect object properties'), LT('تتعرف على Get-Member ومفهوم Property/Method.', 'Explorer propriétés et méthodes avec Get-Member.', 'Use Get-Member to discover properties and methods.'), LT('Get-Member يعرض أنواع الأعضاء: Property للقيم وMethod للعمليات. قد ترى على الشاشة أعمدة قليلة لكن الكائن يحمل خصائص أخرى.', 'Get-Member liste les propriétés et méthodes; l’affichage ne montre qu’une partie des données.', 'Get-Member reveals properties and methods; screen formatting may hide much of an object.'), 'Get-Process | Get-Member', 'Get-Process | Get-Member', LT('اكتشف الاسم الصحيح للخاصية قبل الفلترة، مثل Name أو Id أو CPU حسب نوع الكائن.', 'Trouvez les noms exacts comme Name ou Id avant de filtrer.', 'Discover exact names such as Name or Id before filtering.'), LT('لا تستخرج الخصائص اعتماداً فقط على شكل Format-Table الظاهر.', 'Ne déduisez pas toutes les propriétés du tableau affiché.', 'Do not assume the displayed table lists every property.'), 'Get-Process | Get-Member', ['Get-Member', 'Get-Process']);
add('p-objects', LT('اختيار خصائص محددة', 'Sélectionner des propriétés', 'Select properties'), LT('تحصل على حقول معينة وعدد محدد من العناصر.', 'Extraire quelques champs et objets.', 'Keep selected fields and records.'), LT('Select-Object -Property يحدد الأعمدة، و-First يحصر العدد. النتائج تبقى كائنات إذا اخترت الخصائص، وليست نصاً بالضرورة.', 'Select-Object -Property choisit les colonnes et -First limite le nombre; le résultat reste un objet.', 'Select-Object -Property picks columns and -First limits count; the result remains object data.'), 'Get-Process | Select-Object -First 5 -Property Name,Id', 'Get-Process | Select-Object -First 5 -Property Name,Id', LT('الـPipeline ينقل كائنات من Get-Process إلى Select-Object.', 'Le pipeline transmet des objets de Get-Process vers Select-Object.', 'The pipeline passes process objects into Select-Object.'), LT('Select-Object يختلف عن Format-Table: الثاني مخصص للعرض في نهاية المعالجة.', 'Select-Object produit des données; Format-Table sert surtout à l’affichage final.', 'Select-Object manipulates data; Format-Table primarily formats final display.'), 'Get-Process | Select-Object -First 5 -Property Name,Id', ['Select-Object', 'Format-Table']);
add('p-objects', LT('الفلترة حسب خاصية', 'Filtrer avec Where-Object', 'Filter by property'), LT('تكتب شرطاً لاختيار كائنات مناسبة.', 'Choisir des objets selon une condition.', 'Choose records matching a condition.'), LT('Where-Object يشغل شرطاً لكل كائن؛ $_ يمثل الكائن الحالي في التعبير. المعامل -eq يقارن بالمساواة، و-like يستخدم wildcards.', 'Where-Object applique une condition à chaque objet; $_ désigne l’objet courant; -eq teste l’égalité.', 'Where-Object evaluates a condition for each object; $_ refers to it and -eq tests equality.'), 'Get-Service | Where-Object { $_.Status -eq "Running" }', 'Get-Service | Where-Object { $_.Status -eq "Running" }', LT('تُفحص خاصية Status وليس نص الجدول كله.', 'La condition teste la propriété Status et non le tableau affiché.', 'The condition uses the Status property, not the formatted table text.'), LT('تأكد من أن الخاصية موجودة؛ استخدم Get-Member عند الشك.', 'Vérifiez la présence de la propriété avec Get-Member.', 'Use Get-Member to verify the property exists.'), 'Get-Service | Where-Object { $_.Status -eq "Running" }', ['Where-Object', 'Get-Service']);
add('p-objects', LT('فرز وتجميع الكائنات', 'Trier et regrouper des objets', 'Sort and group objects'), LT('تجهز تقريراً مرتباً أو تجميعاً حسب حالة.', 'Préparer un classement et un regroupement.', 'Prepare sorted and grouped reports.'), LT('Sort-Object يفرز حسب خاصية، وGroup-Object يجمع العناصر المتشابهة. إن استعملت Format-Table في الوسط فقد تفقد خصائص الكائنات الأصلية.', 'Sort-Object trie et Group-Object regroupe par propriété. Évitez Format-Table au milieu d’un pipeline de données.', 'Sort-Object sorts and Group-Object groups by property. Avoid formatting too early in a data pipeline.'), 'Get-Service | Group-Object Status', 'Get-Service | Group-Object Status\nGet-Process | Sort-Object Name', LT('التجميع يحسب عناصر كل حالة، والفرز يعيد ترتيب عمليات حسب اسمها.', 'Le regroupement compte les statuts; le tri classe les noms.', 'Grouping counts service states; sorting orders processes by name.'), LT('الفرز النصي ليس ترتيباً عددياً إذا كانت القيم Strings وليست أرقاماً.', 'Un tri lexical est différent d’un tri numérique.', 'Text sorting is different from numeric sorting.'), 'Get-Service | Group-Object Status', ['Sort-Object', 'Group-Object']);
// POWERSHELL · 05 · Data
add('p-data', LT('استيراد ملفات CSV', 'Importer des fichiers CSV', 'Import CSV into objects'), LT('تستورد الصفوف ككائنات ذات أسماء أعمدة.', 'Importer des lignes en objets aux propriétés nommées.', 'Import rows as objects with named properties.'), LT('Import-Csv يستخدم صف العناوين لإنشاء خصائص. يمكنك بعدها استخدام Where-Object وSelect-Object بطريقة منظمة.', 'Import-Csv transforme l’en-tête en propriétés; vous pouvez ensuite filtrer les objets.', 'Import-Csv turns header cells into properties, letting you filter and select rows as objects.'), 'Import-Csv FILE.csv | Select-Object -First N', 'Import-Csv data/users.csv | Select-Object -First 3', LT('على عكس Get-Content الذي يعيد نصاً، Import-Csv يعطي كائنات تمثل الصفوف.', 'À la différence de Get-Content, Import-Csv crée des objets de ligne.', 'Unlike Get-Content, Import-Csv returns row objects.'), LT('الفاصل ليس دائماً فاصلة عادية؛ راجع -Delimiter إن كان CSV بنقطة فاصلة.', 'Certains CSV utilisent ; : consultez -Delimiter.', 'Some CSV files use semicolons; check the -Delimiter option.'), 'Import-Csv data/users.csv | Select-Object -First 3', ['Import-Csv', 'Export-Csv']);
add('p-data', LT('إخراج التقارير كـCSV', 'Exporter des rapports CSV', 'Export reports as CSV'), LT('تحفظ كائنات قابلة للفرز والاستيراد لاحقاً.', 'Enregistrer des objets réimportables.', 'Save objects for later structured import.'), LT('Export-Csv يكتب أسماء الخصائص وقيمها. اختر الخصائص قبل التصدير، وتجنب Format-Table قبل Export-Csv.', 'Export-Csv écrit les propriétés et leurs valeurs; sélectionnez les colonnes avant l’export.', 'Export-Csv writes property names and values. Select relevant properties before exporting.'), 'OBJECTS | Export-Csv FILE.csv -NoTypeInformation', 'Get-Process | Select-Object Name,Id | Export-Csv reports.csv\nGet-Content reports.csv', LT('الملف الناتج يحتفظ بعناوين الأعمدة؛ عند إعادة استيراده يمكن استعمال Where-Object.', 'Le fichier exporté contient des colonnes réutilisables avec Import-Csv.', 'Exported columns can be re-imported and filtered.'), LT('لا تصدر نتائج Format-Table كـCSV: ستصدر كائنات التنسيق لا البيانات.', 'N’exportez pas Format-Table vers CSV : il produit des objets de mise en forme.', 'Do not export Format-Table output as CSV; it produces formatting objects.'), 'Get-Process | Select-Object Name,Id | Export-Csv reports.csv', ['Export-Csv', 'Select-Object']);
add('p-data', LT('التعامل مع JSON', 'Manipuler JSON', 'Work with JSON'), LT('تحول بين كائنات PowerShell ونص JSON.', 'Convertir objets et texte JSON.', 'Convert objects to and from JSON text.'), LT('ConvertTo-Json ينتج نص JSON، وConvertFrom-Json يفكك JSON إلى كائنات. الخيار -Depth يؤثر على الكائنات المتداخلة في PowerShell الحقيقي.', 'ConvertTo-Json produit du JSON, ConvertFrom-Json reconstruit des objets. -Depth compte pour les objets imbriqués.', 'ConvertTo-Json serializes objects, ConvertFrom-Json deserializes them. -Depth matters for nested data.'), 'OBJECTS | ConvertTo-Json | ConvertFrom-Json', 'Get-Process | Select-Object -First 2 Name,Id | ConvertTo-Json', LT('قارن بين النص JSON الناتج والبيانات الجدولية السابقة.', 'Comparez le texte JSON produit avec les propriétés d’origine.', 'Compare serialized JSON with the original object properties.'), LT('لا تستخدم النص JSON مباشرةً كأنه كائن دون ConvertFrom-Json.', 'Une chaîne JSON n’est pas encore un objet : convertissez-la.', 'JSON text is not yet an object; deserialize it first.'), 'Get-Process | Select-Object -First 2 Name,Id | ConvertTo-Json', ['ConvertTo-Json', 'ConvertFrom-Json', 'Test-Json']);
add('p-data', LT('القياس ومعالجة كل عنصر', 'Mesurer et traiter chaque objet', 'Measure and transform each object'), LT('تستخدم Measure-Object وForEach-Object لإعداد ملخص.', 'Compter et transformer les objets.', 'Count and transform records.'), LT('Measure-Object يحسب عدداً أو مجموعاً حسب الخصائص والمعاملات، وForEach-Object ينفذ كتلة على كل عنصر في الـPipeline.', 'Measure-Object compte ou additionne; ForEach-Object applique un bloc à chaque objet.', 'Measure-Object counts or computes aggregates; ForEach-Object applies a block to each pipeline item.'), 'OBJECTS | Measure-Object | ForEach-Object { ... }', 'Get-Process | Measure-Object\nGet-Content names.txt | ForEach-Object { $_ }', LT('ليس كل عمود رقمياً؛ لا تطلب Sum لخاصية نصية.', 'Ne demandez pas de somme sur une propriété textuelle.', 'Do not sum a text property.'), LT('ForEach-Object ليس هو نفسه حلقة foreach اللغوية رغم تشابه المهمة.', 'ForEach-Object et l’instruction foreach ne sont pas identiques.', 'ForEach-Object and the foreach language loop are related but not identical.'), 'Get-Process | Measure-Object', ['Measure-Object', 'ForEach-Object']);
// POWERSHELL · 06 · System
add('p-system', LT('مراقبة العمليات', 'Observer les processus', 'Inspect processes'), LT('تقرأ اسم العملية وPID وبعض الخصائص.', 'Lire nom de processus, PID et propriétés.', 'Read process names, IDs and properties.'), LT('Get-Process يعيد كائنات عمليات؛ المعامل -Id يختار عملية محددة في PowerShell الحقيقي. لا توقف عملية مجهولة الهوية.', 'Get-Process retourne des objets; -Id choisit un processus précis. Ne terminez pas un processus inconnu.', 'Get-Process returns objects; -Id targets a PID in real PowerShell. Do not terminate unidentified processes.'), 'Get-Process | Select-Object Name,Id', 'Get-Process | Select-Object Name,Id', LT('استعمل اختيار الخصائص لإنشاء تقرير واضح.', 'Sélectionnez des propriétés pour produire un rapport lisible.', 'Select a few properties for a readable process report.'), LT('معرّفات العمليات المعروضة في المختبر نماذج تعليمية.', 'Les PID du laboratoire sont des valeurs simulées.', 'The lab uses sample PIDs, not actual process IDs.'), 'Get-Process | Select-Object Name,Id', ['Get-Process', 'Stop-Process']);
add('p-system', LT('فهم حالات الخدمات', 'Comprendre les services', 'Understand service states'), LT('تستكشف حالة الخدمات وتتجنب تعديلها عشوائياً.', 'Examiner les statuts sans modification inutile.', 'Inspect service status without unnecessary changes.'), LT('Get-Service يعرض أسماء الخدمات وحالاتها مثل Running وStopped. خدمات النظام قد تكون حساسة للتغيير.', 'Get-Service renvoie les services et des statuts comme Running ou Stopped. Les modifier peut affecter le système.', 'Get-Service lists services and statuses such as Running or Stopped. Changing services can affect system stability.'), 'Get-Service | Where-Object { $_.Status -eq "Running" }', 'Get-Service\nGet-Service | Group-Object Status', LT('Group-Object يساعدك تفهم عدد الخدمات في كل حالة من دون إيقاف أي شيء.', 'Group-Object compte les services dans chaque état sans les modifier.', 'Group-Object counts services per state without changing them.'), LT('لا تفترض أن حالة Stopped تعني وجود مشكلة؛ بعض الخدمات تعمل عند الحاجة فقط.', 'Stopped n’est pas toujours une panne : certains services démarrent à la demande.', 'Stopped does not necessarily indicate a problem; some services start on demand.'), 'Get-Service | Group-Object Status', ['Get-Service', 'Start-Service', 'Stop-Service']);
add('p-system', LT('متغيرات الجلسة والبيئة', 'Variables de session et environnement', 'Session and environment variables'), LT('تعرف $var و$env:NAME والفارق بينهما.', 'Distinguer $var et $env:NAME.', 'Distinguish $var from $env:NAME.'), LT('متغيرات PowerShell تبدأ بـ$، أما متغيرات البيئة فتستخدم $env:NAME. يتباين نطاق المتغير حسب Scope وبيئة التشغيل.', 'Les variables PowerShell utilisent $, les variables d’environnement $env:NAME; leur portée dépend du contexte.', 'PowerShell variables use $, environment variables use $env:NAME. Scope and lifetime depend on context.'), '$team="network" | Get-Variable | Set-Variable', 'Set-Variable -Name team -Value network\nGet-Variable team', LT('Get-Variable يعرض متغير الجلسة؛ لا تعامله مثل قيمة Environment المسجلة على الجهاز.', 'Get-Variable lit la session, pas forcément une variable système persistante.', 'Get-Variable reads session variables, not necessarily persistent machine environment settings.'), LT('تخزين أسرار في متغير نصي عادي لا يوفّر حماية آمنة للسر.', 'Une variable texte ordinaire n’est pas un coffre-fort pour secrets.', 'A regular string variable is not secure secret storage.'), 'Set-Variable -Name team -Value network; Get-Variable team', ['Get-Variable', 'Set-Variable']);
add('p-system', LT('رسائل الخطأ والنجاح', 'Erreurs et résultats', 'Errors and success'), LT('تفرق بين Error Stream وOutput Stream.', 'Différencier sortie et erreurs.', 'Distinguish output from errors.'), LT('PowerShell يرسل الأخطاء إلى Error Stream، وليس كل خطأ يوقف السكربت تلقائياً. -ErrorAction Stop يجعل بعض الأخطاء قابلة للاعتراض في try/catch.', 'PowerShell possède un flux d’erreurs; -ErrorAction Stop convertit certaines erreurs en erreurs bloquantes.', 'PowerShell has an error stream; -ErrorAction Stop can make some errors terminating and catchable.'), 'Get-Item MISSING -ErrorAction Stop', 'Test-Path missing.txt\nGet-Item missing.txt', LT('إرجاع False من Test-Path ليس خطأ؛ أما Get-Item لمسار غير موجود فيعيد رسالة خطأ.', 'False pour Test-Path n’est pas une exception; Get-Item manquant peut produire une erreur.', 'False from Test-Path is not an exception; getting a missing item causes an error.'), LT('لا تستعمل try/catch لتجاهل كل الأخطاء دون تسجيلها.', 'N’ignorez pas toutes les erreurs sans journal ni traitement.', 'Do not silently discard all errors inside catch blocks.'), 'Test-Path missing.txt', ['Test-Path', 'Get-Item']);
// POWERSHELL · 07 · Network
add('p-network', LT('قراءة إعدادات IPv4 وIPv6', 'Lire IPv4 et IPv6', 'Inspect IPv4 and IPv6'), LT('تقرأ عنوان الشبكة والواجهة والبادئة.', 'Lire adresse, interface et préfixe.', 'Read addresses, interface and prefix.'), LT('Get-NetIPAddress يعرض عناوين IP على Windows، ويمكن تحديد AddressFamily في PowerShell الحقيقي. وجود IPv6 لا يعني انعدام IPv4 والعكس.', 'Get-NetIPAddress affiche les adresses sur Windows. IPv4 et IPv6 peuvent fonctionner simultanément.', 'Get-NetIPAddress reports Windows IP addressing; IPv4 and IPv6 commonly coexist.'), 'Get-NetIPAddress | Get-NetIPConfiguration', 'Get-NetIPAddress\nGet-NetIPConfiguration', LT('افهم الفرق بين InterfaceAlias وIPAddress وPrefixLength قبل التفكير في أي تغيير.', 'Distinguez InterfaceAlias, IPAddress et PrefixLength avant modification.', 'Distinguish InterfaceAlias, IPAddress and PrefixLength before changing settings.'), LT('مخرجات المختبر ليست إعدادات حاسوبك؛ لا تستخدمها لنسخ إعدادات حقيقية.', 'Le laboratoire ne montre pas la configuration réelle de votre machine.', 'The lab’s networking output is virtual, not your machine’s configuration.'), 'Get-NetIPAddress', ['Get-NetIPAddress', 'Get-NetIPConfiguration']);
add('p-network', LT('التوجيه وDefault Gateway', 'Routage et passerelle', 'Routing and default gateway'), LT('تتعرف على جدول التوجيه والتعامل مع وجهة الشبكة.', 'Comprendre les routes et la passerelle.', 'Understand routes and gateways.'), LT('Get-NetRoute يعرض الوجهات والبوابات ومقاييس المسار في Windows. تغيير المسارات قد يقطع الاتصال، لذلك يبدأ التشخيص بالقراءة فقط.', 'Get-NetRoute donne destinations et passerelles. Modifier une route peut interrompre le réseau.', 'Get-NetRoute lists destinations and gateways in Windows. Changing routes can disconnect networking.'), 'Get-NetRoute | Get-NetIPConfiguration', 'Get-NetRoute', LT('اقرأ DestinationPrefix وNextHop لتحديد مسار خروج الحزم.', 'Lisez DestinationPrefix et NextHop pour comprendre le chemin choisi.', 'Read DestinationPrefix and NextHop to understand packet forwarding.'), LT('لا تحذف Default Route في جهاز تعتمد عليه قبل تجهيز طريقة استرجاع.', 'Ne supprimez pas la route par défaut d’un système actif sans stratégie de retour.', 'Do not delete a default route on a production machine without recovery access.'), 'Get-NetRoute', ['Get-NetRoute', 'Remove-NetRoute']);
add('p-network', LT('اختبار TCP والاتصال', 'Tester TCP et connectivité', 'Test TCP connectivity'), LT('تميّز بين ICMP وTCP واختبار اسم المضيف.', 'Distinguer ICMP et test TCP.', 'Distinguish ICMP and TCP connection tests.'), LT('Test-Connection يختبر ICMP غالباً، وTest-NetConnection -Port يفحص الوصول إلى منفذ TCP. نجاح DNS منفصل عن نجاح اتصال خدمة معينة.', 'Test-Connection teste généralement ICMP; Test-NetConnection -Port vérifie une connexion TCP.', 'Test-Connection usually checks ICMP; Test-NetConnection -Port tests TCP reachability.'), 'Test-NetConnection HOST -Port 443 | Test-Connection HOST', 'Test-NetConnection localhost -Port 80\nTest-Connection localhost', LT('فحص المنفذ لا يثبت أن التطبيق يفهم البروتوكول المطلوب؛ إنه طبقة تشخيص واحدة.', 'Un port accessible ne prouve pas le bon fonctionnement de l’application.', 'A reachable port does not prove that the application protocol works.'), LT('اختبارات المحاكي عينات؛ لا تجرى أي حزم شبكة فعلية.', 'Le labo ne transmet aucun paquet réel sur le réseau.', 'The browser simulator sends no actual network packets.'), 'Test-NetConnection localhost -Port 80', ['Test-NetConnection', 'Test-Connection']);
add('p-network', LT('التشخيص دون تغيير إعدادات Firewall', 'Diagnostiquer sans modifier le pare-feu', 'Diagnose without changing firewall'), LT('ترتب خطوات التشخيص قبل تعديل قواعد الحماية.', 'Ordonner les contrôles avant tout changement.', 'Sequence checks before modifying firewall rules.'), LT('ابدأ بـIP وRoute ثم DNS وTCP ثم Logs. فتح منفذ في Firewall لا يعالج غياب خدمة تستمع عليه، وقد يزيد سطح الهجوم.', 'Vérifiez IP, route, DNS, TCP et journaux avant des règles de pare-feu.', 'Check IP, routes, DNS, TCP and logs before considering firewall rule changes.'), 'Get-NetIPAddress | Get-NetRoute | Test-NetConnection HOST -Port N', 'Get-NetIPAddress\nGet-NetRoute\nTest-NetConnection localhost -Port 80', LT('هذه أوامر قراءة واختبار في المختبر؛ لا تغيّر إعدادات الجهاز الحقيقي.', 'Les commandes du labo ne modifient pas le pare-feu de votre ordinateur.', 'These lab commands do not change your actual firewall.'), LT('تفعيل Allow Any-Any لحل مشكلة خدمة ليس ممارسة آمنة.', 'Une règle Allow Any-Any n’est pas une méthode de diagnostic sûre.', 'An allow-any-any rule is not a safe troubleshooting shortcut.'), 'Get-NetIPAddress', ['Get-NetIPAddress', 'Get-NetRoute', 'Test-NetConnection']);
// POWERSHELL · 08 · Automation
add('p-automation', LT('المتغيرات والتعابير', 'Variables et expressions', 'Variables and expressions'), LT('تتعامل مع أنواع القيم في PowerShell.', 'Manipuler différents types de valeurs.', 'Work with typed values in PowerShell.'), LT('يمكن لمتغير PowerShell أن يحمل نصاً أو رقماً أو كائناً. $x=3 لا يشبه $x="3" دائماً في المقارنات والحساب.', 'Une variable peut contenir texte, nombre ou objet. 3 et "3" n’ont pas toujours le même comportement.', 'A PowerShell variable can hold text, numbers or objects. 3 and "3" are not always equivalent.'), '$name = "student" | $count = 3', 'Set-Variable -Name score -Value 3\nGet-Variable score', LT('Get-Variable يكشف اسم المتغير وقيمته في الجلسة، بينما المعالجة الحسابية تحتاج نوعاً مناسباً.', 'Get-Variable montre la valeur; les opérations arithmétiques supposent un type adapté.', 'Get-Variable reveals values; arithmetic still depends on appropriate types.'), LT('لا تخلط = (إسناد) مع -eq (مقارنة).', 'Ne confondez pas = (affectation) et -eq (égalité).', 'Do not confuse assignment = with comparison -eq.'), 'Set-Variable -Name score -Value 3; Get-Variable score', ['Set-Variable', 'Get-Variable']);
add('p-automation', LT('الشروط والفروع', 'Conditions et branches', 'Conditions and branches'), LT('تستعمل if مع شرط Boolean صحيح.', 'Utiliser if et les booléens.', 'Use if with Boolean conditions.'), LT('if (Test-Path $path) يفحص قيمة Boolean، و-else يعالج الحالة الأخرى. يمكن استعمال -and و-or لتركيب شروط، لكن تجنب التعقيد غير الضروري.', 'if teste une condition booléenne; else traite l’autre cas. -and et -or combinent les conditions.', 'if checks a Boolean condition; else handles the other branch. -and and -or combine conditions.'), 'if (Test-Path FILE) { "exists" } else { "missing" }', 'Test-Path notes.txt', LT('المحاكي يدعم Test-Path، أما جملة if الكاملة فتتطلب جلسة PowerShell فعلية.', 'Le simulateur gère Test-Path; une instruction if complète demande PowerShell réel.', 'The simulator handles Test-Path; full if statements require a real PowerShell shell.'), LT('PowerShell يستعمل -eq للمقارنة، وليس == في غالبية حالات الاستعمال.', 'La comparaison habituelle utilise -eq, pas ==.', 'PowerShell comparisons commonly use -eq, not ==.'), 'Test-Path notes.txt', ['Test-Path', 'Where-Object']);
add('p-automation', LT('الحلقات ومعالجة مجموعات', 'Boucles et collections', 'Loops and collections'), LT('تعالج عدة عناصر باستعمال ForEach-Object أو foreach.', 'Parcourir des collections avec foreach.', 'Process collections with ForEach-Object or foreach.'), LT('foreach حلقة لغة، بينما ForEach-Object يستقبل الكائنات من Pipeline. $_ داخل ForEach-Object يشير إلى العنصر الحالي.', 'foreach est une structure de langage, ForEach-Object consomme le pipeline et utilise $_ pour l’élément courant.', 'foreach is a language loop; ForEach-Object receives pipeline objects and uses $_ for the current item.'), 'Get-Content FILE | ForEach-Object { $_ }', 'Get-Content names.txt | ForEach-Object { $_ }', LT('ابدأ بتصفية وعرض القيم قبل إضافة تعديل يغيّر ملفات حقيقية.', 'Affichez d’abord les éléments avant d’y appliquer des modifications.', 'Print or inspect items before adding real-world mutating actions.'), LT('حلقات كبيرة مع عمليات بطيئة قد تحتاج معالجة وتسجيل أخطاء مستقلين.', 'Les grandes boucles demandent une bonne gestion des erreurs.', 'Large loops benefit from per-item error handling.'), 'Get-Content names.txt | ForEach-Object { $_ }', ['ForEach-Object', 'Get-Content']);
add('p-automation', LT('السكربتات ومعالجة الاستثناءات', 'Scripts et gestion des exceptions', 'Scripts and error handling'), LT('تبني خطوات واضحة وتمنع تجاهل الأخطاء.', 'Structurer un script et traiter ses erreurs.', 'Structure scripts and handle failures.'), LT('السكربت .ps1 يتكوّن من أوامر وتعريفات، ويمكنك استخدام param() لتعريف المدخلات. try/catch يلتقط الأخطاء المنهِية فقط؛ استخدم -ErrorAction Stop عند الحاجة.', 'Un script .ps1 peut déclarer param(). try/catch capte les erreurs bloquantes; utilisez -ErrorAction Stop si nécessaire.', 'A .ps1 script may declare inputs with param(). try/catch catches terminating errors; use -ErrorAction Stop where appropriate.'), 'param([string]$Path)\ntry { Get-Item $Path -ErrorAction Stop } catch { Write-Error $_ }', 'Get-Help Get-Item\nTest-Path notes.txt', LT('جرّب خطوات القراءة أولاً ثم اكتب سكربتاً في PowerShell الحقيقي؛ المختبر لا ينفذ ملفات .ps1.', 'Testez d’abord les commandes en lecture; le laboratoire n’exécute pas de vrais fichiers .ps1.', 'Test read-only steps first in your real shell; the browser lab cannot execute .ps1 scripts.'), LT('لا تعطل ExecutionPolicy أو الحماية لإجبار سكربت مجهول على التشغيل.', 'N’affaiblissez pas les protections pour un script non fiable.', 'Do not weaken security settings to run unknown scripts.'), 'Get-Help Get-Item', ['Get-Help', 'Get-Item']);
